// Course UI: a single active controller. Content never determines completion by itself.
let insightReturn109=null;
function coursePercent109(id){const l=DATA.lessons.find(x=>x.id===id);return l?Learning109.percent(state.readSeen?.[id],l.course_pages.length):0}
function remember(captureScroll=true){if(!session||session.id==='review')return;if(captureScroll&&session.step===1)session.readingWindowScroll=window.scrollY||0;state.readSeen??={};state.readSeen[session.id]??=[];if(session.step===1&&!state.readSeen[session.id].includes(session.readingPage||0))state.readSeen[session.id].push(session.readingPage||0);const article=document.querySelector('.course-reading');if(captureScroll&&session.step===1&&article&&Number.isFinite(article.scrollTop))session.readingScroll=article.scrollTop;state.lastCourse=session.id;state.resume={id:session.id,step:session.step,qi:session.qi||0,chosen:session.chosen??null,revealed:!!session.revealed,readingPage:session.readingPage||0,readingScroll:session.readingScroll||0,readingWindowScroll:session.readingWindowScroll||0,qids:session.qs?.map(q=>q.id)||[],practiceMode:session.practiceMode,practiceOffset:session.practiceOffset||0,historyOrigin:session.historyOrigin||false};state.courseProgress??={};state.courseProgress[session.id]={...state.resume};state.courseSessions??={};const oldContext=state.courseSessions[session.id]||{};const practice=session.practiceMode?{ids:session.qs.map(q=>q.id),index:session.qi||0,choice:session.chosen??null,revealed:!!session.revealed,courseId:session.id,mode:session.practiceMode}:undefined;state.courseSessions[session.id]={...oldContext,readingPage:session.readingPage||0,readingScroll:session.readingScroll||0,mode:session.step===2?'practice':'reading',returnOrigin:session.historyOrigin?'history':'catalog',practice};state.courseStatus??={};const readPercent=coursePercent109(session.id);const previous=state.courseStatus[session.id]||{};state.courseStatus[session.id]={...previous,readPercent,readCompleted:readPercent===100};save()}
function nextChapter109(l){const i=DATA.lessons.findIndex(x=>x.id===l.id);return DATA.lessons[i+1]||null}
function returnCourseReading109(snapshot){if(snapshot)session={...snapshot};session.step=1;tab='courses';selectedCard=null;lessonView();const article=document.querySelector('.course-reading');if(article)article.scrollTop=session.readingScroll||0;window.scrollTo(0,session.readingWindowScroll||0);remember()}
function start(id){const l=DATA.lessons.find(x=>x.id===id);if(!l?.ready)return toast('本课暂不可用');const ctx=state.courseSessions?.[id];const r=ctx?{step:ctx.mode==='practice'?2:1,qids:ctx.practice?.ids,qi:ctx.practice?.index,chosen:ctx.practice?.choice,revealed:ctx.practice?.revealed,practiceMode:ctx.practice?.mode,readingPage:ctx.readingPage,readingScroll:ctx.readingScroll,historyOrigin:ctx.returnOrigin==='history',readingWindowScroll:state.courseProgress?.[id]?.readingWindowScroll}:state.courseProgress?.[id]||(state.resume?.id===id?state.resume:{});const qs=(r.qids||[]).map(qid=>l.questions.find(q=>q.id===qid)||FLOW108.bank.find(q=>q.id===qid)).filter(Boolean).map(courseQuestion109);session={id,step:r.step===2&&qs.length?2:1,qi:Math.min(r.qi||0,Math.max(0,qs.length-1)),chosen:r.chosen??null,revealed:!!r.revealed,qs:qs.length?qs:l.questions,readingPage:Math.min(r.readingPage||0,l.course_pages.length-1),readingScroll:r.readingScroll||0,readingWindowScroll:r.readingWindowScroll||0,practiceMode:r.practiceMode,practiceOffset:r.practiceOffset||0,historyOrigin:r.historyOrigin||false};tab='courses';selectedCard=null;lessonView();const article=document.querySelector('.course-reading');if(session.step===1){if(article)article.scrollTop=session.readingScroll;window.scrollTo(0,session.readingWindowScroll||0)}remember()}
function openCourseCard109(name){const c=PKT_CARDS.find(c=>c.name===name);if(!c)return;remember();state.courseReturn={id:session.id,page:session.readingPage,session:{...session},scrollTop:session.readingScroll||0};selectedCard=c.card_id;session=null;cardView()}
function bindCourseReading(l){const turn=d=>{const n=(session.readingPage||0)+d;if(n<0||n>=l.course_pages.length)return;remember();session.readingPage=n;session.readingScroll=0;const panel=$('#course-reading-panel');panel.innerHTML=courseReading(l);bindReadingPanel(l);remember()};$('#reading-prev').onclick=()=>turn(-1);$('#reading-next').onclick=()=>turn(1)}
function insight109(l){remember();const note={...freshNote(),type:'life',courseId:l.id,title:'',courseContext:{page:session.readingPage}};insightReturn109={noteId:note.id,session:{...session}};journalFlush=null;oldEditJournal108(note);const heading=document.querySelector('#app h1');if(heading)heading.textContent='记录妙想';const leave=()=>{if(journalFlush&&journalFlush()===false)return;const ctx=insightReturn109;insightReturn109=null;journalFlush=null;returnCourseReading109(ctx.session)};$('#back-notes').onclick=leave;$('#discard-note').onclick=()=>journalConfirm('放弃这份草稿？','未保存文字会被清除，返回课程原位置。','放弃',()=>{const old=state.noteDrafts[note.id];delete state.noteDrafts[note.id];if(!save()){if(old)state.noteDrafts[note.id]=old;return false}journalFlush=null;const ctx=insightReturn109;insightReturn109=null;returnCourseReading109(ctx.session)})}
const standardViewJournal109=viewJournal;
viewJournal=function(id){if(insightReturn109?.noteId===id){const ctx=insightReturn109;insightReturn109=null;journalFlush=null;returnCourseReading109(ctx.session);return}standardViewJournal109(id)};
function bindAnimations109(){stopAnimations109();document.querySelectorAll('[data-animation]').forEach(fig=>{const a=ANIM109[fig.dataset.animation],frame=fig.querySelector('.animation-frame'),button=fig.querySelector('[data-animation-play]');let n=0,timer=null;const draw=()=>frame.style.backgroundPosition=(n%a.cols)/(a.cols-1)*100+'% '+Math.floor(n/a.cols)/(a.rows-1)*100+'%';const status=running=>{button.innerHTML=animationIcon109(running?'pause':'play');button.setAttribute('aria-label',running?'暂停动画':'播放动画');button.setAttribute('aria-pressed',String(running));button.title=running?'暂停':'播放'};const pause=()=>{if(timer)clearInterval(timer);timer=null;status(false)};const play=()=>{if(n>=a.count-1)n=0;draw();timer=setInterval(()=>{if(!fig.isConnected)return pause();n++;draw();if(n>=a.count-1)pause()},180);animationTimers109.push(timer);status(true)};button.onclick=()=>timer?pause():play();fig.querySelector('[data-animation-replay]').onclick=()=>{pause();n=0;play()};const stage=fig.querySelector('.animation-stage');stage.onclick=e=>{if(!e.target.closest('button')&&matchMedia('(hover: none), (pointer: coarse)').matches)stage.classList.toggle('controls-visible')};stage.onkeydown=e=>{if(e.target===stage&&['Enter',' '].includes(e.key)){e.preventDefault();stage.classList.toggle('controls-visible')}};draw();status(false)})}
