bindReadingPanel=function(l){remember(false);bindCourseReading(l);bindTextbookLayout(l);bindTeachingTasks(l);bindSpreadTeaching();document.querySelectorAll('[data-course-card]').forEach(b=>b.onclick=()=>openCourseCard109(b.dataset.courseCard));const panel=$('#course-reading-panel'),sections=l.sections||[],current=sections.findIndex(s=>session.readingPage>=s.start&&session.readingPage<=s.end);if(sections.length>1){panel.insertAdjacentHTML('afterbegin','<details class="section-menu"><summary><span class="section-caption">小节</span><span class="section-current">'+E(sections[current]?.title||'本课学习')+'</span><span class="section-count">'+(current+1)+' / '+sections.length+'</span><svg class="section-chevron" viewBox="0 0 20 20" aria-hidden="true"><path d="m5 8 5 5 5-5"/></svg></summary><div class="section-options">'+sections.map((s,i)=>'<button class="section-option '+(i===current?'is-current':'')+'" data-section-index="'+i+'"><span class="section-number">'+String(i+1).padStart(2,'0')+'</span><span>'+E(s.title)+'</span>'+(i===current?'<span class="section-check">✓</span>':'')+'</button>').join('')+'</div></details>');document.querySelectorAll('[data-section-index]').forEach(b=>b.onclick=()=>{remember();session.readingPage=sections[Number(b.dataset.sectionIndex)].start;session.readingScroll=0;panel.innerHTML=courseReading(l);bindReadingPanel(l)})}const meta=document.querySelector('.course-meta');if(meta)meta.textContent=l.stage+' · 学习进度 '+coursePercent109(l.id)+'%';const progressBar=document.querySelector('#course-reading-panel .reading-progress i');if(progressBar)progressBar.setAttribute('style','width:'+coursePercent109(l.id)+'%');$('#fresh-practice').textContent=session.practiceMode&&session.qs.length?'继续练习':'练习本课';$('#fresh-practice').onclick=()=>{remember();practiceChooser109(l)};if($('#resume-practice'))$('#resume-practice').classList.add('hidden');$('#lesson-note').textContent='记录妙想';$('#lesson-note').onclick=()=>insight109(l);$('#learning-return').textContent='学习下一章';$('#learning-return').onclick=()=>{remember();const next=nextChapter109(l);if(next)start(next.id);else{session=null;courseStage=l.stage;navigate('courses')}};const article=document.querySelector('.course-reading');if(article){article.scrollTop=session.readingScroll||0;article.onscroll=()=>{session.readingScroll=article.scrollTop;state.courseProgress[session.id].readingScroll=article.scrollTop;if(state.courseSessions?.[session.id])state.courseSessions[session.id].readingScroll=article.scrollTop;save()}}bindAnimations109();measureReadingSpace109()};
function courseNavigation109(l){const next=nextChapter109(l);return '<div class="lesson-routebar"><button class="link" id="course-route-back">← 返回课程</button>'+(next?'<button class="link" id="course-route-next">学习下一章 →</button>':'')+'</div>'}
function bindRoutes109(l){$('#course-route-back').onclick=()=>returnCourseReading109();if($('#course-route-next'))$('#course-route-next').onclick=()=>{remember();start(nextChapter109(l).id)}}
lessonView=function(){const l=session.id==='review'?session.lesson:DATA.lessons.find(l=>l.id===session.id);if(session.id==='review'){beforeLessonFlow109();return}if(session.step===1){$('#app').innerHTML='<div class="narrow"><button class="link" id="back">← 返回目录</button><h1>'+E(l.title)+'</h1><div class="steps"><span class="active">学习解析</span><span>练习</span><span>回顾</span></div><section class="panel"><div id="course-reading-panel">'+courseReading(l)+'</div></section></div>';$('#back').textContent=session.historyOrigin?'← 返回能力档案':'← 返回目录';$('#back').onclick=()=>{remember();const origin=session.historyOrigin;session=null;if(origin)history109();else{courseStage=l.stage;navigate('courses')}};bindReadingPanel(l);return}if(session.step===2){if(!session.qs.length){session.step=1;lessonView();return}const q=session.qs[session.qi],key=q.answer_key;$('#app').innerHTML='<div class="narrow">'+courseNavigation109(l)+'<h1>'+E(l.title)+'</h1><div class="steps"><span>学习解析</span><span class="active">练习</span><span>回顾</span></div><section class="panel"><p class="tip">练习 '+(session.qi+1)+' / '+session.qs.length+' · 不影响阅读进度</p><h2>'+E(q.prompt)+'</h2>'+questionContext109(q)+q.options.map(o=>'<button class="option '+(session.chosen===o.id?'selected':'')+'" data-course-option="'+o.id+'">'+o.id+'　'+E(o.text)+'</button>').join('')+(session.chosen||session.revealed?'<div class="feedback"><strong>参考答案：'+E(key.answer)+'</strong><p>原因：'+E(key.reason)+'</p>'+q.options.map(o=>'<p>'+o.id+'：'+E(o.feedback)+'</p>').join('')+'</div><button class="primary" id="course-question-next">'+(session.qi+1<session.qs.length?'下一题':'查看本组回顾')+'</button>':'<button class="link" id="course-reveal">先看答案与解释</button>')+'</section></div>';bindRoutes109(l);document.querySelectorAll('[data-course-card]').forEach(b=>b.onclick=()=>openCourseCard109(b.dataset.courseCard));document.querySelectorAll('[data-course-option]').forEach(b=>b.onclick=()=>{if(!session.chosen){state.attempts.push({qid:q.id,lesson:l.id,answer:b.dataset.courseOption,correct:q.accepted_option_ids.includes(b.dataset.courseOption),revealed:session.revealed,independent:!session.revealed,date:day()})}session.chosen=b.dataset.courseOption;state.courseStatus??={};state.courseStatus[l.id]={...state.courseStatus[l.id],practiced:true};remember();lessonView()});if($('#course-reveal'))$('#course-reveal').onclick=()=>{session.revealed=true;remember();lessonView()};if($('#course-question-next'))$('#course-question-next').onclick=()=>{if(session.qi+1<session.qs.length){session.qi++;session.chosen=null;session.revealed=false}else session.step=3;remember();lessonView()};return}const records=session.qs.map(q=>({q,a:state.attempts.filter(a=>a.lesson===l.id&&a.qid===q.id).slice(-1)[0]}));state.courseStatus??={};state.courseStatus[l.id]={...state.courseStatus[l.id],practiced:true,needsReview:records.some(r=>!r.a?.correct||r.a?.revealed)};session.practiceMode=null;remember();$('#app').innerHTML='<div class="narrow">'+courseNavigation109(l)+'<h1>本组练习回顾</h1><p>阅读进度 '+coursePercent109(l.id)+'% · 练习完成不等于课程读完或能力掌握。</p>'+records.map(r=>'<section class="panel"><h3>'+E(r.q.prompt)+'</h3><p>'+(!r.a?'已查看解释':r.a.revealed?'提示后作答':r.a.correct?'独立回答正确':'建议回看')+'</p><p>'+E(r.q.answer_key.reason)+'</p></section>').join('')+'</div>';bindRoutes109(l);if($('#group-more'))$('#group-more').onclick=()=>beginCourseGroup109(l,l.questions,'course')};
