const previousMineFinal109=mine;
mine=function(){previousMineFinal109();const stats=document.querySelector('.stats');if(stats)stats.innerHTML='<div class="stat"><b>'+DATA.lessons.filter(l=>coursePercent109(l.id)===100).length+'</b><span>已读完课程</span></div><div class="stat"><b>'+Object.values(state.courseStatus||{}).filter(x=>x.practiced).length+'</b><span>已练习课程</span></div><div class="stat"><b>'+Object.values(state.courseStatus||{}).filter(x=>x.needsReview).length+'</b><span>待巩固课程</span></div>'};
