function practiceChooser109(l){const current=Learning109.sectionPool(l,session.readingPage);$('#app').innerHTML='<div class="narrow">'+courseNavigation109(l)+'<h1>'+E(l.title)+' · 练习</h1><section class="panel"><p>每组最多8题，练习不影响阅读百分比。</p><button class="primary" id="choose-section">练当前小节 · '+E(current.section?.title||'本课')+'</button>'+(current.fallback?'<p class="tip">本小节暂无独立题，将使用全课巩固题。</p>':'')+'<button class="secondary" id="choose-course">全课练习</button><button class="secondary" id="choose-due">复习待练题</button>'+(session.practiceMode&&session.qs.length?'<button class="secondary" id="choose-resume">继续未完成题组</button>':'')+(COMPARE_CASES109.some(c=>c.course===l.id)?'<button class="secondary" id="choose-compare">比较两种解释</button>':'')+'</section></div>';bindRoutes109(l);$('#choose-section').onclick=()=>beginCourseGroup109(l,current.pool,'section');$('#choose-course').onclick=()=>beginCourseGroup109(l,l.questions,'course');$('#choose-due').onclick=()=>beginCourseGroup109(l,l.questions.filter(q=>Learning109.due(state.attempts||[],q.id)),'due');if(session.practiceMode&&session.qs.length)$('#choose-resume').onclick=()=>{session.step=2;remember();lessonView()};if(COMPARE_CASES109.some(c=>c.course===l.id))$('#choose-compare').onclick=()=>comparePractice109(l)}
const historyBeforeEvidence1018=history109;
history109=function(){historyBeforeEvidence1018();const records=(state.attempts||[]).filter(a=>a.lesson).slice(-30).reverse();$('#app').insertAdjacentHTML('beforeend','<section class="panel"><h2>课程练习证据 · 最近30次</h2>'+records.map(a=>{const l=DATA.lessons.find(l=>l.id===a.lesson),q=l?.questions.find(q=>q.id===a.qid);return '<div class="study-block"><p>'+E(q?.knowledge_point||'课程应用')+' · '+E(q?.prompt||a.qid)+'</p><p>'+E(a.revealed?'提示后作答':a.correct?'独立正确':'待巩固')+' · 选择 '+E(a.answer)+'</p><button class="link" data-evidence-course="'+E(a.lesson)+'">回看相关课程</button></div>'}).join('')+'</section>');document.querySelectorAll('[data-evidence-course]').forEach(b=>b.onclick=()=>{start(b.dataset.evidenceCourse);session.historyOrigin=true;remember(false);lessonView()})};
